bash -lc 'set -e; p="/src/openexr/src/lib/OpenEXRCore/internal_huf.c"; 
# 1: insert a global guard pointer after first include
sed -i "/^#include/ a static const uint8_t* fasthuf_table_end = NULL;" "$p"; 
# 2: set end pointer in fasthuf_initialize after fhd->_maxCodeLength = 0;
awk 'BEGIN{patched=0} {print} /fhd->_maxCodeLength = 0;/ && !patched { print "    if (table && *table) fasthuf_table_end = (*table) + numBytes;"; patched=1 }' "$p" > "$p.tmp" && mv "$p.tmp" "$p"; 
# 3: guard fasthuf_read_bits loop to avoid over-read
perl -0777 -pe 's/while \(\*bufferNumBits < numBits\)
\s*\{
\s*\*buffer = \(\*buffer\) << 8\) \| \*\(\*currByte\)\+\+;
\s*\*bufferNumBits \+\= 8;
\s*\}/while (*bufferNumBits < numBits)
    {
        if (fasthuf_table_end && *currByte >= fasthuf_table_end) { break; }
        *buffer = ((*buffer) << 8) | *((*currByte)++);
        *bufferNumBits += 8;
    }/s' "$p" > "$p.tmp" && mv "$p.tmp" "$p"'

