# 3 patch fasthuf_read_bits to guard against end-of-table
python3 - << 'PY'
p = "/src/openexr/src/lib/OpenEXRCore/internal_huf.c"
import io,sys
with open(p, 'r', encoding='utf-8') as f:
    s = f.read()
old = '''static inline uint64_t
fasthuf_read_bits (
    int numBits, uint64_t* buffer, int* bufferNumBits, const uint8_t** currByte)
{
    while (*bufferNumBits < numBits)
    {
        *buffer = ((*buffer) << 8) | *((*currByte)++);
        *bufferNumBits += 8;
    }

    *bufferNumBits -= numBits;
    return ((*buffer) >> (*bufferNumBits)) & ((1 << numBits) - 1);
}'''
new = '''static inline uint64_t
fasthuf_read_bits (
    int numBits, uint64_t* buffer, int* bufferNumBits, const uint8_t** currByte)
{
    while (*bufferNumBits < numBits)
    {
        if (fasthuf_table_end != NULL && *currByte >= fasthuf_table_end) {
            break;
        }
        *buffer = ((*buffer) << 8) | *((*currByte)++);
        *bufferNumBits += 8;
    }

    if (*bufferNumBits < numBits) {
        return 0;
    }

    *bufferNumBits -= numBits;
    return ((*buffer) >> (*bufferNumBits)) & ((1 << numBits) - 1);
}'''
if old in s:
    s = s.replace(old, new)
else:
    print('Old block not found, abort patch')
    sys.exit(1)
with open(p,'w', encoding='utf-8') as f:
    f.write(s)
print('Patched fasthuf_read_bits')
PY'

